"""NTFS 备用数据流的读写。

Windows 上每个文件除了主数据之外，还可以挂若干条**备用数据流**
（Alternate Data Stream, ADS）。从浏览器或下载器落地的文件通常会被写入一条
名为 ``Zone.Identifier`` 的流，用来记录它来自哪个区域（互联网、内网等）。

备用数据流通过 ``路径:流名`` 的语法访问，它有自己独立的大小与内容，
与主数据毫无关系；查询大小时必须 stat 流本身，而不是宿主文件。
"""

import os

from .errors import StreamError

#: 下载来源标记使用的备用流名。
ZONE_STREAM = "Zone.Identifier"


def stream_path(path, name):
    """返回 ``path`` 上名为 ``name`` 的备用数据流的可访问路径。"""
    return "%s:%s" % (path, name)


def stream_exists(path, name):
    """``path`` 上是否存在名为 ``name`` 的备用数据流。"""
    try:
        os.stat(stream_path(path, name))
    except (OSError, ValueError):
        # 宿主文件不存在、流不存在或路径非法，都视作「没有这条流」。
        return False
    return True


def stream_size(path, name):
    """返回备用数据流自身的字节数；流不存在时返回 ``0``。

    注意这里取的是流的长度，而不是宿主文件主数据的长度。
    """
    target = stream_path(path, name)
    if not stream_exists(path, name):
        return 0
    try:
        return os.path.getsize(target)
    except (OSError, ValueError):
        return 0


def read_stream(path, name):
    """读回备用数据流的内容；流不存在时抛 :class:`StreamError`。"""
    target = stream_path(path, name)
    if not stream_exists(path, name):
        raise StreamError("stream %r not present on %r" % (name, path))
    with open(target, "rb") as fh:
        return fh.read()


def write_stream(path, name, data):
    """写入（或覆盖）一条备用数据流。"""
    with open(stream_path(path, name), "wb") as fh:
        fh.write(bytes(data))


def remove_stream(path, name):
    """删除一条备用数据流；流不存在时返回 ``False``。"""
    target = stream_path(path, name)
    if not stream_exists(path, name):
        return False
    try:
        os.remove(target)
    except FileNotFoundError:
        return False
    return True

"""清除文件的「来自互联网」标记。"""

from .streams import ZONE_STREAM, remove_stream, stream_exists


def is_blocked(path):
    """``path`` 是否带有来自互联网的标记。"""
    return stream_exists(path, ZONE_STREAM)


def unblock(path):
    """清除 ``path`` 上的来自互联网标记。

    返回是否真的发生了变化：带标记的文件被清除后返回 ``True``；
    本来就没有标记（或宿主文件不存在）时返回 ``False``，不抛异常，
    因此批量脚本可以安全地对整棵目录树重复调用。
    """
    return remove_stream(path, ZONE_STREAM)

